/**
 * Contract tests: the hand-written API types the app uses (src/types/api.ts)
 * must describe the same shapes as the backend's OpenAPI schema
 * (src/types/openapi.d.ts, generated by `npm run api:types`).
 *
 * The checks are at the type level, so `npm run typecheck` (tsc) is what
 * fails on a mismatch; the test below only keeps vitest aware of the file.
 * String literal unions in the app (for example CompetitionStatus) are
 * compared as `string`, because the backend schema types them as strings.
 */
import type { components } from "@/types/openapi";
import type * as Api from "@/types/api";

type Schemas = components["schemas"];

/** Literal unions become their base types; objects and arrays are widened recursively. */
type Widen<T> = T extends string
  ? string
  : T extends number
    ? number
    : T extends boolean
      ? boolean
      : T extends null | undefined
        ? T
        : T extends readonly (infer U)[]
          ? Widen<U>[]
          : T extends object
            ? { [K in keyof T]-?: Widen<Exclude<T[K], undefined>> }
            : T;

type SameKeys<A, B> = [Exclude<keyof A, keyof B> | Exclude<keyof B, keyof A>] extends [never] ? true : false;
type MutuallyAssignable<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false;
/** Same field names, and each field compatible once literal unions are widened. */
export type Matches<App, Schema> =
  SameKeys<App, Schema> extends true ? MutuallyAssignable<Widen<App>, Widen<Schema>> : ["field names differ", Exclude<keyof App, keyof Schema>, Exclude<keyof Schema, keyof App>];

function contract<T extends true>(): T | undefined {
  return undefined;
}

// Responses
contract<Matches<Api.User, Schemas["UserOut"]>>();
contract<Matches<Api.UserStatistics, Schemas["UserStatistics"]>>();
contract<Matches<Api.ExecuteResponse, Schemas["ExecuteResponse"]>>();
contract<Matches<Api.Explanation, Schemas["ExplanationOut"]>>();
contract<Matches<Api.QuestionSummary, Schemas["QuestionSummary"]>>();
contract<Matches<Api.QuestionDetail, Schemas["QuestionDetail"]>>();
contract<Matches<Api.Example, Schemas["ExampleOut"]>>();
contract<Matches<Api.Submission, Schemas["SubmissionOut"]>>();
contract<Matches<Api.Snippet, Schemas["SnippetOut"]>>();
contract<Matches<Api.Participant, Schemas["ParticipantOut"]>>();
contract<Matches<Api.Winner, Schemas["WinnerOut"]>>();
contract<Matches<Api.CompetitionState, Schemas["CompetitionState"]>>();
contract<Matches<Api.CompetitionListItem, Schemas["CompetitionListItem"]>>();
contract<Matches<Api.PlayerResult, Schemas["PlayerResult"]>>();
contract<Matches<Api.ResultSubmission, Schemas["ResultSubmission"]>>();
contract<Matches<Api.CompetitionResults, Schemas["CompetitionResults"]>>();
contract<Matches<Api.FocusPolicy, Schemas["FocusPolicy"]>>();
contract<Matches<Api.FocusState, Schemas["FocusStateOut"]>>();
contract<Matches<Api.FocusEventResult, Schemas["FocusEventResult"]>>();

describe("API contract", () => {
  it("is checked by the TypeScript compiler (npm run typecheck)", () => {
    expect(contract<true>()).toBeUndefined();
  });
});
